/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */
import { readFileSync } from 'node:fs'

class Fail extends Error {
  constructor(message, code = 2) {
    super(message)
    this.code = code
  }
}

const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const tasks = new Map()
  const depLines = []
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const w = line.split(/\s+/)
    const n = i + 1
    if (w[0] === 'task') {
      if (w.length !== 3) throw new Fail(`error: line ${n}: expected task <name> <cost>`)
      if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) throw new Fail(`error: line ${n}: invalid task name ${w[1]}`)
      if (!/^[0-9]+$/.test(w[2])) throw new Fail(`error: line ${n}: cost must be a non-negative integer`)
      if (tasks.has(w[1])) throw new Fail(`error: line ${n}: task ${w[1]} is declared twice`)
      tasks.set(w[1], { name: w[1], cost: Number(w[2]), deps: new Set() })
    } else if (w[0] === 'dep') {
      if (w.length < 3) throw new Fail(`error: line ${n}: expected dep <name> <dependency>...`)
      for (const name of w.slice(1)) {
        if (!/^[A-Za-z0-9_.-]+$/.test(name)) throw new Fail(`error: line ${n}: invalid task name ${name}`)
      }
      depLines.push(w.slice(1))
    } else {
      throw new Fail(`error: line ${n}: unknown directive ${w[0]}`)
    }
  })
  for (const names of depLines) {
    for (const name of names) if (!tasks.has(name)) throw new Fail(`error: unknown task ${name}`)
  }
  for (const [name, ...deps] of depLines) for (const d of deps) tasks.get(name).deps.add(d)
  return tasks
}

function findCycle(tasks) {
  const names = [...tasks.keys()].sort(cmp)
  const state = new Map()
  const stack = []
  const visit = (name) => {
    state.set(name, 1)
    stack.push(name)
    for (const d of [...tasks.get(name).deps].sort(cmp)) {
      const s = state.get(d)
      if (s === 1) return [...stack.slice(stack.indexOf(d)), d]
      if (!s) {
        const c = visit(d)
        if (c) return c
      }
    }
    stack.pop()
    state.set(name, 2)
    return null
  }
  for (const n of names) {
    if (!state.get(n)) {
      const c = visit(n)
      if (c) return c
    }
  }
  return null
}

function schedule(tasks) {
  const names = [...tasks.keys()].sort(cmp)
  const info = new Map()
  const calc = (name) => {
    let r = info.get(name)
    if (r) return r
    const t = tasks.get(name)
    let start = 0
    let depth = 0
    for (const d of t.deps) {
      const x = calc(d)
      start = Math.max(start, x.finish)
      depth = Math.max(depth, x.depth + 1)
    }
    r = { start, finish: start + t.cost, depth }
    info.set(name, r)
    return r
  }
  names.forEach(calc)
  let total = 0
  for (const r of info.values()) total = Math.max(total, r.finish)
  return { names, info, total }
}

function pack(tasks, names, workers) {
  const prio = new Map()
  const dependents = new Map(names.map((n) => [n, []]))
  for (const n of names) for (const d of tasks.get(n).deps) dependents.get(d).push(n)
  const pr = (n) => {
    if (prio.has(n)) return prio.get(n)
    let best = 0
    for (const m of dependents.get(n)) best = Math.max(best, pr(m))
    const v = tasks.get(n).cost + best
    prio.set(n, v)
    return v
  }
  names.forEach(pr)
  const freeAt = new Array(workers).fill(0)
  const runs = Array.from({ length: workers }, () => [])
  const finish = new Map()
  let pending = names.slice()
  let t = 0
  let makespan = 0
  while (pending.length > 0) {
    for (;;) {
      const w = freeAt.findIndex((f) => f <= t)
      if (w < 0) break
      let pick = -1
      for (let i = 0; i < pending.length; i++) {
        const n = pending[i]
        let ok = true
        for (const d of tasks.get(n).deps) {
          const f = finish.get(d)
          if (f === undefined || f > t) { ok = false; break }
        }
        if (!ok) continue
        if (pick < 0 || pr(n) > pr(pending[pick])) pick = i
      }
      if (pick < 0) break
      const n = pending[pick]
      pending.splice(pick, 1)
      const f = t + tasks.get(n).cost
      finish.set(n, f)
      freeAt[w] = f
      runs[w].push(`${n}@${t}-${f}`)
      makespan = Math.max(makespan, f)
    }
    if (pending.length === 0) break
    let next = Infinity
    for (const f of freeAt) if (f > t && f < next) next = f
    if (next === Infinity) break
    t = next
  }
  const out = runs.map((r, i) => `worker ${i}:${r.map((x) => ' ' + x).join('')}`)
  out.push(`makespan ${makespan}`)
  return out
}

function main(argv) {
  const mode = argv[0]
  let workers = 0
  if (mode === 'pack' && argv.length === 2) {
    if (!/^[1-9][0-9]*$/.test(argv[1])) throw new Fail('error: workers must be a positive integer')
    workers = Number(argv[1])
  } else if (!((mode === 'waves' || mode === 'explain') && argv.length === 1)) {
    throw new Fail('error: usage: cli.js waves|explain|pack <workers>')
  }
  const tasks = parse(readFileSync(0, 'utf8'))
  const cycle = findCycle(tasks)
  if (cycle) throw new Fail(`error: cycle: ${cycle.join(' -> ')}`, 3)
  const { names, info, total } = schedule(tasks)
  const out = []
  if (mode === 'waves') {
    const waves = []
    for (const n of names) (waves[info.get(n).depth] ??= []).push(n)
    waves.forEach((w, k) => out.push(`wave ${k}: ${w.join(' ')}`))
    out.push(`total ${total}`)
  } else if (mode === 'explain') {
    for (const n of names) {
      const r = info.get(n)
      out.push(`${n} start=${r.start} finish=${r.finish} depth=${r.depth}`)
    }
    out.push(`total ${total}`)
  } else {
    out.push(...pack(tasks, names, workers))
  }
  return out.join('\n') + '\n'
}

try {
  process.stdout.write(main(process.argv.slice(2)))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exit(e.code)
}
