function findCycle(tasks) {
  const names = [...tasks.keys()].sort(cmp)
  const state = new Map()
  const stack = []
  const visit = (name) => {
    state.set(name, 1)
    stack.push(name)
    for (const d of [...tasks.get(name).deps].sort(cmp)) {
      const s = state.get(d)
      if (s === 1) return [...stack.slice(stack.indexOf(d)), d]
      if (!s) {
        const c = visit(d)
        if (c) return c
      }
    }
    stack.pop()
    state.set(name, 2)
    return null
  }
